INSERT INTO boe_inject.unit_version_stage (id,unit_id,body,valid_from,evidence_instrument,evidence_url,evidence_quote) VALUES
('boe26-5ab5e2ad6e292891836eb9a4','cmpzcv47a09imvtrkd3tdfv5u','يصدر وزير التجارة - بالاتفاق مع كل من وزارات: ( الداخلية، والصحة، والبيئة والمياه والزراعة، والصناعة والثروة المعدنية، والشؤون البلدية والقروية والإسكان)، والهيئة العامة للغذاء والدواء - اللائحة التنفيذية لهذا النظام','2021-11-11','مرسوم ملكي رقم م/31 وتاريخ 1443/4/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/4c55f487-89fa-4d0f-80f1-a9a700f2835e/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/31) وتاريخ 1443/4/6هـ، لتكون بالنص الآتي:

"يصدر وزير التجارة - بالاتفاق مع كل من وزارات: ( الداخلية، والصحة، والبيئة والمياه والزراعة، والصناعة والثروة المعدنية، والشؤون البلدية والقروية والإسكان)، والهيئة العامة للغذاء والدواء - اللائحة التنفيذية لهذا النظام".'),
('boe26-2a30025ac75853d671d5ef02','cmpz9er1l0cgzybvvjjzcnxje','تبدأ السنة المالية للمؤسسة من أول شهر يناير وتنتهي بنهاية شهر ديسمبر من كل عام ميلادي','2019-04-02','قرار مجلس الوزراء رقم 429 وتاريخ 26/7/1440هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/5160cfca-da74-4008-97e2-a9a700f23b92/1','•المادة الثانية عشرة

-عُدلت هذه المادة بموجب قرار مجلس الوزراء رقم (429) وتاريخ 26 /7 / 1440هـ، لتكون بالنص الآتي: "تبدأ السنة المالية للمؤسسة من أول شهر يناير وتنتهي بنهاية شهر ديسمبر من كل عام ميلادي".

 '),
('boe26-f3264c4db8cfd3b47cd2cd6e','cmpzcvbts0bojvtrktcoy9nt7','تنشأ بمقتضى هذا التنظيم جمعية تسمى الجمعية السعودية للمراجعين الداخليين، وهي جمعية مهنية ذات شخصية اعتبارية وذمة مالية مستقلة، تعمل تحت إشراف الجهة التي يصدر بتحديدها أمر من رئيس مجلس الوزراء بناءً على اقتراح مجلس الشؤون الاقتصادية والتنمية، مقرها الرئيس مدينة الرياض. ولها –بقرار من مجلس الإدارة- إنشاء فروع أو مكاتب ف مدن أخرى داخل المملكة','2020-09-08','قرار مجلس الوزراء رقم 57 وتاريخ 20/1/1442هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/5203b65e-bf51-4e81-8701-a9a700f2d4b7/1','- عُدلت هذه المادة بموجب قرار مجلس الوزراء رقم (57) وتاريخ 20 / 1 / 1442هـ، لتكون بالنص الآتي:

" تنشأ بمقتضى هذا التنظيم جمعية تسمى الجمعية السعودية للمراجعين الداخليين، وهي جمعية مهنية ذات شخصية اعتبارية وذمة مالية مستقلة، تعمل تحت إشراف الجهة التي يصدر بتحديدها أمر من رئيس مجلس الوزراء بناءً على اقتراح مجلس الشؤون الاقتصادية والتنمية، مقرها الرئيس مدينة الرياض. ولها –بقرار من مجلس الإدارة- إنشاء فروع أو مكاتب ف مدن أخرى داخل المملكة".'),
('boe26-f726af8cf6e441f01a06dcad','cmpzcut6e06isvtrkvmi3ks5j','كل من يخالف أحكام هذا النظام ولوائحه التنفيذية يعاقب بغرامة لا تتجاوز مائة ألف ريـال، ويجوز تضمين قرار العقوبة النص على نشر منطوقه على نفقة المخالف في صحيفة محلية تصدر في مكان إقامته، فإن لم يكن في مكان إقامته صحيفة ففي أقرب منطقة له، أو نشره في أي وسيلة أخرى مناسبة، وذلك بحسب نوع المخالفة المرتكبة وجسامتها وآثارها، على أن يكون نشر القرار بعد تحصنه بمضي المدة المحددة نظاما أو تأييده من المحكمة المختصة','2017-01-17','مرسوم ملكي رقم م/37 وتاريخ 19/4/1438هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/588efd09-dc0d-4491-82e4-a9a700f245f6/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/37) بتاريخ 19/ 4/ 1438هـ، لتصبح بالنص الآتي:

"كل من يخالف أحكام هذا النظام ولوائحه التنفيذية يعاقب بغرامة لا تتجاوز مائة ألف ريـال، ويجوز تضمين قرار العقوبة النص على نشر منطوقه على نفقة المخالف في صحيفة محلية تصدر في مكان إقامته، فإن لم يكن في مكان إقامته صحيفة ففي أقرب منطقة له، أو نشره في أي وسيلة أخرى مناسبة، وذلك بحسب نوع المخالفة المرتكبة وجسامتها وآثارها، على أن يكون نشر القرار بعد تحصنه بمضي المدة المحددة نظاما أو تأييده من المحكمة المختصة"'),
('boe26-62cf4c4de0e6f29dbbe3fbbc','cmpzcv7lk0ajwvtrkvasra2qf','أولاً: أن يكون التقديم على طلب دعم الصندوق قبل نهاية 31 ديسمبر 2022م.

ثانياً: أن يكون مبلغ دعم الصندوق هو (30%) من راتب المستفيد، ويضاف عليه نسب الدعم التفضيلي (10%) بحسب الشروط والأحكام الصادرة من مجلس إدارة الصندوق، على ألا يتجاوز مبلغ الدعم (3000) ريال.

ثالثاً: أن يكون دعم الصندوق لنشاط الإيواء السياحي في مدينتي (مكة المكرمة، والمدينة المنورة).

رابعاً: أن يستمر المستفيد -خلال السنة الإضافية- في المرفق السياحي الذي تم طلب الدعم عليه.

خامساً: ألا يكون المرفق السياحي من ضمن قائمة المنشآت المستبعدة من دعم الصندوق.','2022-11-15','قرار مجلس الوزراء رقم 297 وتاريخ 1444/4/21هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/5a16cf9b-e1b8-426f-82ab-a9a700f2a640/1','- عُدلت مدة تحمل الصندوق لمن دعمهم الصندوق مسبقاً في مدينتي ( مكة المكرمة، و المدينة المنورة ) لتكون ثلاث سنوات بدلاً من سنتين، وذلك بموجب قرار مجلس الوزراء رقم (297) وتاريخ 1444/4/21هـ، وتكون وفقاً للآتي:

أولاً: أن يكون التقديم على طلب دعم الصندوق قبل نهاية 31 ديسمبر 2022م.

ثانياً: أن يكون مبلغ دعم الصندوق هو (30%) من راتب المستفيد، ويضاف عليه نسب الدعم التفضيلي (10%) بحسب الشروط والأحكام الصادرة من مجلس إدارة الصندوق، على ألا يتجاوز مبلغ الدعم (3000) ريال.

ثالثاً: أن يكون دعم الصندوق لنشاط '),
('boe26-0e9a3ce9cefcea540d39cb5e','cmpz61pa903b7cwg233xu7b8g','يدرس المركز الطلب، بعد استكمال المتطلبات المشار إليها في المادة (الرابعة) من النظام؛ للنظر في الموافقة - ما لم تقتضِ المصلحة خلاف ذلك - على منح المتقدم الإقامة المميزة، وتصدر بقرار من رئيس المركز، وذلك وفقاً للأحكام الواردة في النظام واللائحة','2023-12-24','مرسوم ملكي رقم م/84 وتاريخ 1445/6/11هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/5e9762df-2b15-4e66-8cdc-aa5200f62042/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/84) وتاريخ 1445/6/11هـ، لتصبح بالنص الآتي:

"يدرس المركز الطلب، بعد استكمال المتطلبات المشار إليها في المادة (الرابعة) من النظام؛ للنظر في الموافقة - ما لم تقتضِ المصلحة خلاف ذلك - على منح المتقدم الإقامة المميزة، وتصدر بقرار من رئيس المركز، وذلك وفقاً للأحكام الواردة في النظام واللائحة".'),
('boe26-47873d30f749dec72db5be97','cmpz6gduo088ncwg2o2h6frn5','1- يقدم طلب الترخيص إلى الهيئة وفقاً للإجراءات التي يحددها المجلس.

2- تصدر الهيئة قرارها بالموافقة على منح الترخيص، أو بالرفض مسبباً لطلب الترخيص، خلال مدة تحددها اللائحة. ولطالب الترخيص التظلم من قرار الرفض أمام المحكمة الإدارية.

3- تحدد اللائحة إجراءات دراسة طلب الترخيص والبت فيه، ومدته وشروط تجديده.

4- يحدد المجلس المقابل المالي للترخيص','2025-02-09','مرسوم ملكي رقم م/169 وتاريخ 1446/8/10هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/6435e205-a7ae-4a8c-9580-ad0000b6bef2/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/169) وتاريخ 1446/8/10هـ، لتصبح بالنص الآتي:

"1- يقدم طلب الترخيص إلى الهيئة وفقاً للإجراءات التي يحددها المجلس.

2- تصدر الهيئة قرارها بالموافقة على منح الترخيص، أو بالرفض مسبباً لطلب الترخيص، خلال مدة تحددها اللائحة. ولطالب الترخيص التظلم من قرار الرفض أمام المحكمة الإدارية.

3- تحدد اللائحة إجراءات دراسة طلب الترخيص والبت فيه، ومدته وشروط تجديده.

4- يحدد المجلس المقابل المالي للترخيص".'),
('boe26-ab8277e40824805b4b43abd9','cmpz6ge03088pcwg236bq94if','دون إخلال بالعقوبات المنصوص عليها في المادة (العاشرة) من النظام، للهيئة إصدار قرار بإلغاء الترخيص. ويجوز لمن صدر قرار إلغاء ترخيصه التظلم منه أمام المحكمة الإدارية. ولا يترتب على إلغاء الترخيص إلغاء عضويته بالهيئة','2025-02-09','مرسوم ملكي رقم م/169 وتاريخ 1446/8/10هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/6435e205-a7ae-4a8c-9580-ad0000b6bef2/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/169) وتاريخ 1446/8/10هـ، لتصبح بالنص الآتي: "دون إخلال بالعقوبات المنصوص عليها في المادة (العاشرة) من النظام، للهيئة إصدار قرار بإلغاء الترخيص. ويجوز لمن صدر قرار إلغاء ترخيصه التظلم منه أمام المحكمة الإدارية. ولا يترتب على إلغاء الترخيص إلغاء عضويته بالهيئة".'),
('boe26-b20df1bef4fc72ab90a56378','cmpz6gg9h089jcwg21ekfjkns','دون إخلال باختصاصات الجهات المعنية، يتولى موظفون من الهيئة -يصدر بتسميتهم قرار من المجلس- ضبط ما يُرتكب من الجرائم المنصوص عليها في المادة (العاشرة) من النظام، وما يُرتكب من مخالفات لأحكام النظام ولائحته والقرارات الصادرة تنفيذاً لهما','2025-02-09','مرسوم ملكي رقم م/169 وتاريخ 1446/8/10هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/6435e205-a7ae-4a8c-9580-ad0000b6bef2/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/169) وتاريخ 1446/8/10هـ، لتصبح بالنص الآتي: "دون إخلال باختصاصات الجهات المعنية، يتولى موظفون من الهيئة -يصدر بتسميتهم قرار من المجلس- ضبط ما يُرتكب من الجرائم المنصوص عليها في المادة (العاشرة) من النظام، وما يُرتكب من مخالفات لأحكام النظام ولائحته والقرارات الصادرة تنفيذاً لهما".'),
('boe26-fb1ab9e95d452f464512a8cd','cmpzcv47a09jdvtrkun9utom0','على كل مؤسسة صحية خاصة تحديد أسعار الخدمات التي تقدمها، ومن ثم تعتمدها الوزارة بعد مراجعتها والتأكد من مناسبتها وفقاً للمعايير التي تضعها، ولا يجوز تعديل هذه الأسعار إلا بعد موافقة الوزارة، وتلتزم المؤسسة بما يأتي:

1 ـ  أسعار الخدمات الصحية المعتمدة.

2 - وضع الأسعار في مكان بارز وبخط واضح.

3 - تقديم تقرير تقريبي للمراجع عن تكلفة العلاج قبل بدئه والخدمات التي ستقدم له.

4 - تقديم بيان تفصيلي نهائي للمراجع عن نوع العلاج والخدمات التي قدمت له وتكلفة كل منها','2014-09-26','مرسوم ملكي رقم م/78 وتاريخ 2/12/1435هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/64e307c5-ac8c-49d8-9174-a9a700f285a0/1','تم تعديل المادة (السابعة) بموجب المرسوم الملكي رقم ( م/78 ) وتاريخ 2 / 12 / 1435 هـ، لتصبح بالنص الآتي:

"على كل مؤسسة صحية خاصة تحديد أسعار الخدمات التي تقدمها، ومن ثم تعتمدها الوزارة بعد مراجعتها والتأكد من مناسبتها وفقاً للمعايير التي تضعها، ولا يجوز تعديل هذه الأسعار إلا بعد موافقة الوزارة، وتلتزم المؤسسة بما يأتي:

1 ـ  أسعار الخدمات الصحية المعتمدة.

2 - وضع الأسعار في مكان بارز وبخط واضح.

3 - تقديم تقرير تقريبي للمراجع عن تكلفة العلاج قبل بدئه والخدمات التي ستقدم له.

4 - تقديم بيان تفصي'),
('boe26-740609f8e1136ddf62702fa0','cmpzcvduf0c7mvtrklyjh7tbx','مع عدم الإخلال بأي عقوبة أشد ينص عليها نظام آخر، يعاقب كل من يرتكب أياً من الأعمال المنصوص عليها في المادة (الثالثة والعشرين) من هذا النظام بغرامة لا تزيد على (خمسة ملايين ريال) أو بالسجن مدة لا تزيد على (خمس سنوات) أو بهما معاً، ويجوز الحكم بمصادرة الأجهزة والمنظومات والبرامج المستخدمة في ارتكاب المخالفة.

وللمحكمة المختصة أن تضمن حكمها النص على نشر ملخصه على نفقة المحكوم عليه في صحيفة محلية تصدر في مكان إقامته، أو في أقرب منطقة له إن لم يكن في مكان إقامته صحيفة محلية، أو بالطريقة التي تراها المحكمة مناسبة، وذلك بحسب نوع الجريمة المرتكبة، وجسامتها، وتأثيرها، على أن يكون النشر بعد اكتساب الحكم الصفة النهائية','2015-05-19','مرسوم ملكي رقم م/57 وتاريخ 1/8/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/6f509360-2c39-4358-ae2a-a9a700f2ed16/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/57) بتاريخ 1 / 8 / 1436هـ، لتصبح بالنص الآتي:

" مع عدم الإخلال بأي عقوبة أشد ينص عليها نظام آخر، يعاقب كل من يرتكب أياً من الأعمال المنصوص عليها في المادة (الثالثة والعشرين) من هذا النظام بغرامة لا تزيد على (خمسة ملايين ريال) أو بالسجن مدة لا تزيد على (خمس سنوات) أو بهما معاً، ويجوز الحكم بمصادرة الأجهزة والمنظومات والبرامج المستخدمة في ارتكاب المخالفة.

وللمحكمة المختصة أن تضمن حكمها النص على نشر ملخصه على نفقة المحكوم عليه في صحيفة محلية تصدر في'),
('boe26-0801738a0a25de2ab622d090','cmpz6mupm0ak7cwg2jll9vhw3','يعاقب بالسجن مدة لا تزيد على سنتين وبغرامة لا تتجاوز مائة ألف ريال، أو بإحدى هاتين العقوبتين؛ كل من تعمد إتلاف أي من تمديدات أو منشآت المرافق العامة، أو تعمد قطعها أو تعطيلها، سواء كان الفاعل أصلياً أو شريكاً، ويجوز تضمين قرار أو حكم العقوبة النص على نشر منطوقه على نفقة المخالف في صحيفة محلية تصدر في مكان إقامته، فإن لم يكن في مكان إقامته صحيفة ففي أقرب منطقة له، أو نشره في أي وسيلة أخرى مناسبة، وذلك بحسب نوع المخالفة المرتكبة وجسامتها وآثارها، على أن يكون النشر بعد تحصن القرار بمضي المدة المحددة نظاماً أو تأييده من المحكمة المختصة، أو باكتساب الحكم الصفة النهائية','2017-01-17','مرسوم ملكي رقم م/38 وتاريخ 19/4/1438هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/70405759-cf34-4260-a81e-a9a700f21241/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/38) بتاريخ 19/ 4/ 1438هـ، لتصبح بالنص الآتي:

"يعاقب بالسجن مدة لا تزيد على سنتين وبغرامة لا تتجاوز مائة ألف ريال، أو بإحدى هاتين العقوبتين؛ كل من تعمد إتلاف أي من تمديدات أو منشآت المرافق العامة، أو تعمد قطعها أو تعطيلها، سواء كان الفاعل أصلياً أو شريكاً، ويجوز تضمين قرار أو حكم العقوبة النص على نشر منطوقه على نفقة المخالف في صحيفة محلية تصدر في مكان إقامته، فإن لم يكن في مكان إقامته صحيفة ففي أقرب منطقة له، أو نشره في أي وسيلة أخرى مناسبة، وذلك ب'),
('boe26-28e3a575be1c61c93b9999f4','cmpz5wh0201k7cwg20qsmi4qx','يحكم على من تثبت إدانته في جريمة الرشوة بمصادرة المال أو الميزة أو الفائدة محل الجريمة متى كان ذلك ممكناً، أو مصادرة قيمته بحسب الأحوال، ومصادرة أي عائدات ترتبت من ذلك المال أو الميزة أو الفائدة','2021-12-02','مرسوم ملكي رقم م/38 وتاريخ 1443/4/27هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/75e963c8-9ff3-4d10-88a4-a9a700f17f21/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/38) وتاريخ 1443/4/27هـ. لتكون بالنص الآتي: "يحكم على من تثبت إدانته في جريمة الرشوة بمصادرة المال أو الميزة أو الفائدة محل الجريمة متى كان ذلك ممكناً، أو مصادرة قيمته بحسب الأحوال، ومصادرة أي عائدات ترتبت من ذلك المال أو الميزة أو الفائدة".'),
('boe26-c5ece67f1ea8822b22d2eadb','cmpzcv7li0ahkvtrkptwt1grl','يخضع منسوبو الهيئة لأحكام نظام العمل ونظام التأمينات الاجتماعية','2021-03-23','قرار مجلس الوزراء رقم 445 وتاريخ 1442/8/10هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/796a6587-8da2-4583-8603-ac4500d5b8bc/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (445) وتاريخ 1442/8/10هـ، لتصبح بالنص الآتي: "يخضع منسوبو الهيئة لأحكام نظام العمل ونظام التأمينات الاجتماعية".'),
('boe26-9ca7efb37a56a38161b650fe','cmpz5y1ty023tcwg22fsjonr5','عند تعديل القيود أو تسجيل الحالات والواقعات المدنية، تُسجّل الخصائص الحيوية لمن بلغ سن (السادسة) من السعوديين. وتحدد اللائحة التنفيذية الضوابط اللازمة لما ورد في هذه المادة','2024-04-01','مرسوم ملكي رقم م/198 وتاريخ 1445/9/22هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/198) وتاريخ 1445/9/22هـ، لتكون بالنص الآتي: 

"عند تعديل القيود أو تسجيل الحالات والواقعات المدنية، تُسجّل الخصائص الحيوية لمن بلغ سن (السادسة) من السعوديين. وتحدد اللائحة التنفيذية الضوابط اللازمة لما ورد في هذه المادة".'),
('boe26-984a9299c425047e0e601fae','cmpz5y2ao023zcwg2t5bdocz1','إذا رفض كاتب السجل المنوط به القيد – قيد أية واقعة مدنية - وجب عليه خلال سبعة أيام رفع الأمر إلى الإدارة التي يتبعها بمذكرة مسببة. وعلى مدير الإدارة أن يبدي رأيه بقرار مكتوب يعلم فيه كلا من كاتب السجل وصاحب الشأن خلال ثلاثين يوما من تاريخ رفع الأمر إليه، وفي حالة رفض القيد أو مضي المدة المذكورة يكون لصاحب الشأن الحق في التظلم إلى   اللجنة  الفرعية.','2001-08-20','مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 /1422 هـ ،لتكون بالنص التالى:

إذا رفض كاتب السجل المنوط به القيد – قيد أية واقعة مدنية - وجب عليه خلال سبعة أيام رفع الأمر إلى الإدارة التي يتبعها بمذكرة مسببة. وعلى مدير الإدارة أن يبدي رأيه بقرار مكتوب يعلم فيه كلا من كاتب السجل وصاحب الشأن خلال ثلاثين يوما من تاريخ رفع الأمر إليه، وفي حالة رفض القيد أو مضي المدة المذكورة يكون لصاحب الشأن الحق في التظلم إلى   اللجنة  الفرعية.'),
('boe26-7f02e20d9c023e39408bd033','cmpz5y2g80241cwg2zs9igcof','عند التبليغ عن واقعة مدنية بعد فوات المدة المحددة وقبل نهاية السنة الأولى لحدوثها، فعلى كاتب السجل أن يتثبت من صحة وقوعها في التاريخ المبلغ عنه، وله في هذا السبيل طلب الإثباتات وإجراء التحقيق اللازم، وعليه بعد ثبوت   الواقعة     تقييدها في السجل الخاص بها. أما في الواقعات التي يبلغ عنها بعد انتهاء سنة من تاريخ حدوثها، فلا يجوز قيدها إلا بقرار من   اللجنة     المحلية.','2001-08-20','مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 / 1422 هـ ،لتكون بالنص التالى:

عند التبليغ عن واقعة مدنية بعد فوات المدة المحددة وقبل نهاية السنة الأولى لحدوثها، فعلى كاتب السجل أن يتثبت من صحة وقوعها في التاريخ المبلغ عنه، وله في هذا السبيل طلب الإثباتات وإجراء التحقيق اللازم، وعليه بعد ثبوت   الواقعة     تقييدها في السجل الخاص بها. أما في الواقعات التي يبلغ عنها بعد انتهاء سنة من تاريخ حدوثها، فلا يجوز قيدها إلا بقرار من   اللجنة     المحلية.'),
('boe26-7eb587eb45a83b2cebdf1aaa','cmpz5y2rd0245cwg2fs5tla84','لا يجوز لكاتب السجل المنوط به القيد أن يسجل أية واقعة يكون هو فيها مبلغا أو طالب قيد أو شاهد، أو تكون متعلقة به أو بزوجه أو أحد أصوله أو فروعه أو أقاربه إلى الدرجة الرابعة، إلا بعد أن يرفع الأمر إلى مدير الإدارة التابع له الذي يقوم بدراسة الأوراق والتأكد من سلامتها ثم يأمر بإجراء القيد اللازم.','2001-08-20','مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 /1422 هـ ،لتكون بالنص التالى:

لا يجوز لكاتب السجل المنوط به القيد أن يسجل أية واقعة يكون هو فيها مبلغا أو طالب قيد أو شاهد، أو تكون متعلقة به أو بزوجه أو أحد أصوله أو فروعه أو أقاربه إلى الدرجة الرابعة، إلا بعد أن يرفع الأمر إلى مدير الإدارة التابع له الذي يقوم بدراسة الأوراق والتأكد من سلامتها ثم يأمر بإجراء القيد اللازم.'),
('boe26-b49f23a942a0cb1b8b4ebc1c','cmpz5y382024bcwg2wbnfgrfm','يهيأ في كل إدارة من إدارات الأحوال المدنية، في كل مكتب من مكاتبها - خزائن خاصة - تحفظ فيها سجلات وأوراق الواقعات، أما معاملات الأحوال المدنية المبنية على هذه الواقعات والمتعلقة بالإضافة إلى السجل المدني أو التعديل فيه أو الحذف منه، فتحفظ في ملف أساس صاحب الشأن بعد إكمال اللازم، ليمكن الرجوع إليها. وتحدد اللائحة التنفيذية طرق وأساليب الحفظ في خزائن المحفوظات وكيفية عمل فهارس واضحة للمحفوظات، بحيث يمكن الرجوع إليها بيسر عند الحاجة','2001-08-20','مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 /1422 هـ ،لتكون بالنص التالى:

يهيأ في كل إدارة من إدارات الأحوال المدنية، في كل مكتب من مكاتبها - خزائن خاصة - تحفظ فيها سجلات وأوراق الواقعات، أما معاملات الأحوال المدنية المبنية على هذه الواقعات والمتعلقة بالإضافة إلى السجل المدني أو التعديل فيه أو الحذف منه، فتحفظ في ملف أساس صاحب الشأن بعد إكمال اللازم، ليمكن الرجوع إليها. وتحدد اللائحة التنفيذية طرق وأساليب الحفظ في خزائن المحفوظات وكيفية عمل فهارس واضحة للمحفوظات، بحيث يمكن الرج'),
('boe26-9ab381009c540fa49e800504','cmpz5y3dm024dcwg20dhu824z','تفحص السجلات عند إيداعها للحفظ في خزائن المحفوظات من قبل   اللجنة     المحلية وعليها أن توقع في نهاية القيود من كل سجل بما يفيد فحصها، وأن تحرر محضرا بنتيجة الفحص تبين فيه حالة هذه السجلات، وما قد يكون فيها من مخالفات تسجيلية، ورفع هذا المحضر إلى   الهيئة  خلال خمسة عشرة يوما من تاريخ إجراء الفحص.','2001-08-20','مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 / 1422هـ ،لتكون بالنص التالى:

تفحص السجلات عند إيداعها للحفظ في خزائن المحفوظات من قبل   اللجنة     المحلية وعليها أن توقع في نهاية القيود من كل سجل بما يفيد فحصها، وأن تحرر محضرا بنتيجة الفحص تبين فيه حالة هذه السجلات، وما قد يكون فيها من مخالفات تسجيلية، ورفع هذا المحضر إلى   الهيئة  خلال خمسة عشرة يوما من تاريخ إجراء الفحص.'),
('boe26-f946b0ee6e15591b4d58fde8','cmpz5y4rq024tcwg2019o9ntt','يكون التبليغ عن المواليد لدى مكتب من مكاتب الأحوال المدنية على النموذج المعد لذلك خلال خمسة عشر يوما من تاريخ الولادة. وتكون هذه المهلة ثلاثين يوما إذا حدثت الولادة في مكان يبعد عن أقرب إدارة أو مكتب للأحوال المدنية أكثر من خمسين كيلا.','2001-08-20','مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 / 1422 هـ ،لتكون بالنص التالى:

يكون التبليغ عن المواليد لدى مكتب من مكاتب الأحوال المدنية على النموذج المعد لذلك خلال خمسة عشر يوما من تاريخ الولادة. وتكون هذه المهلة ثلاثين يوما إذا حدثت الولادة في مكان يبعد عن أقرب إدارة أو مكتب للأحوال المدنية أكثر من خمسين كيلا.'),
('boe26-673afaf14a412ba9f7be53df','cmpz5y5e00251cwg2wjh0jege','إذا توفي مولود قبل قيده في السجل، وجب تسجيل ولادته ثم تسجيل وفاته. أما إذا ولد ميتا بعد الشهر السادس من الحمل فيقيد في سجل الوفيات بأنه ولد ميتا.','2001-08-20','مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 /1422 هـ ،لتكون بالنص التالى:

إذا توفي مولود قبل قيده في السجل، وجب تسجيل ولادته ثم تسجيل وفاته. أما إذا ولد ميتا بعد الشهر السادس من الحمل فيقيد في سجل الوفيات بأنه ولد ميتا.'),
('boe26-9641812f82d62f1b6db99662','cmpz5y5pa0255cwg2wne5pluk','يجب على المؤسسة أو الشخص الذي عهد إليه برعاية الطفل اللقيط تبليغ   مكتب الأحوال المدنية     المختص بذلك خلال خمسة عشر يوما من تاريخ تسلمه اللقيط. وعلى كاتب السجل قيده في السجل كالمتبع، وتسلم شهادة ميلاد الطفل إلى المؤسسة أو الشخص الذي تكفل بتربيته ورعايته دون أن يذكر فيه أنه لقيط. وفي حالة معرفة أحد الوالدين أو كليهما يتم تصحيح قيد الطفل بقرار من   اللجنة     الفرعية.','2001-08-20','مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 /1422 هـ ،لتكون بالنص التالى:

يجب على المؤسسة أو الشخص الذي عهد إليه برعاية الطفل اللقيط تبليغ   مكتب الأحوال المدنية     المختص بذلك خلال خمسة عشر يوما من تاريخ تسلمه اللقيط. وعلى كاتب السجل قيده في السجل كالمتبع، وتسلم شهادة ميلاد الطفل إلى المؤسسة أو الشخص الذي تكفل بتربيته ورعايته دون أن يذكر فيه أنه لقيط. وفي حالة معرفة أحد الوالدين أو كليهما يتم تصحيح قيد الطفل بقرار من   اللجنة     الفرعية.'),
('boe26-693a953f8b6dfea2ebd556ea','cmpz5y9vm026ncwg2s6u40wcm','يجب على من أكمل سن الخامسة عشرة من المواطنين السعوديين أن يحصل على بطاقة شخصية هوية وطنية خاصة به، ويكون ذلك اختياريًا لمن هم بين سن العاشرة والخامسة عشرة بعد موافقة ولي أمره، وتستخرج البطاقة من واقع قيود السجل المدني المركزي.','2013-04-02','مرسوم ملكي رقم م/28 وتاريخ 21/5/1434هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/28) وتاريخ 21 / 5 /1434 هـ ،لتكون بالنص الآتى:

يجب على من أكمل سن الخامسة عشرة من المواطنين السعوديين أن يحصل على بطاقة شخصية هوية وطنية خاصة به، ويكون ذلك اختياريًا لمن هم بين سن العاشرة والخامسة عشرة بعد موافقة ولي أمره، وتستخرج البطاقة من واقع قيود السجل المدني المركزي.'),
('boe26-65bf4c6a4e0dc0bf64d93257','cmpz5y9vm026ncwg2s6u40wcm','يجب أن يحصل من أكمل سن (الخامسة عشرة) من السعوديين على بطاقة شخصية خاصة به، ويقوم وليه أو وصيه أو وكيل أي منهما بالإجراءات المطلوبة لذلك، ويكون ذلك اختيارياً لمن هم بين سن (السادسة) و(الخامسة عشرة)، وتستخرج البطاقة من واقع قيود السجل المدني المركزي.

وتحدد اللائحة التنفيذية الضوابط اللازمة لما ورد في هذه المادة','2024-04-01','مرسوم ملكي رقم م/198 وتاريخ 1445/9/22هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/198) وتاريخ 1445/9/22هـ ، لتكون بالنص الآتي: 

" يجب أن يحصل من أكمل سن (الخامسة عشرة) من السعوديين على بطاقة شخصية خاصة به، ويقوم وليه أو وصيه أو وكيل أي منهما بالإجراءات المطلوبة لذلك، ويكون ذلك اختيارياً لمن هم بين سن (السادسة) و(الخامسة عشرة)، وتستخرج البطاقة من واقع قيود السجل المدني المركزي.

وتحدد اللائحة التنفيذية الضوابط اللازمة لما ورد في هذه المادة".'),
('boe26-64058e0eeae77f51a65de33f','cmpz5yayk0271cwg2734acf8h','1 -  يعطى دفتر العائلة لمدة غير محددة، وإذا توفي صاحبه يسحب ويصرف بدلا منه دفتر عائلة آخر باسم المتوفى لكل من يرغب من ورثته المضافين فيه، على أن يؤثر مكان الصورة بما يفيد أنه متوفى.
2 – تحدد اللائحة التنفيذية مدة صلاحية البطاقة الشخصية من تاريخ صدورها، أو استبدالها، أو تجديدها. ويجب تجديدها خلال مائة وثمانين يوما سابقة لانقضاء مدة صلاحيتها.','2005-04-13','مرسوم ملكي رقم م/11 وتاريخ 4/3/1426هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة أكثر من مرة ، كان آخرها بموجب المرسوم الملكي رقم (م/11) وتاريخ 4 / 3 / 1426 هـ ، لتكون بالنص الآتى:

"1 -  يعطى دفتر العائلة لمدة غير محددة، وإذا توفي صاحبه يسحب ويصرف بدلا منه دفتر عائلة آخر باسم المتوفى لكل من يرغب من ورثته المضافين فيه، على أن يؤثر مكان الصورة بما يفيد أنه متوفى.
2 – تحدد اللائحة التنفيذية مدة صلاحية البطاقة الشخصية من تاريخ صدورها، أو استبدالها، أو تجديدها. ويجب تجديدها خلال مائة وثمانين يوما سابقة لانقضاء مدة صلاحيتها."'),
('boe26-52e5c23810c2d5e846372db6','cmpz5yc75027hcwg2v73ye7zc','أ - تشكل بقرار من   وزير الداخلية وبقدر الحاجة لجان محلية في كل إدارة أو مكتب للأحوال المدنية، وتتكون كل لجنة من:

1 - مندوب من   إدارة الأحوال المدنية     يعينه   وزير الداخلية    أو من ينيبه.
2 - مندوب من وزارة العدل يعينه وزير العدل أو من ينيبه.
3 - مندوب من وزارة الصحة يعينه وزير الصحة أو من ينيبه.

ب - تشكل بقرار من   وزير الداخلية  وبقدر الحاجة لجان فرعية في المناطق، وتتكون كل لجنة من:

1 - مستشار يعينه وزير الداخلية.
2  -  مندوب يعينه وزير العدل.
3 - مندوب يعينه وزير الصحة.','2001-08-20','مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 / 1422هـ ، لتكون بالنص الآتى:

" أ - تشكل بقرار من   وزير الداخلية وبقدر الحاجة لجان محلية في كل إدارة أو مكتب للأحوال المدنية، وتتكون كل لجنة من:

1 - مندوب من   إدارة الأحوال المدنية     يعينه   وزير الداخلية    أو من ينيبه.
2 - مندوب من وزارة العدل يعينه وزير العدل أو من ينيبه.
3 - مندوب من وزارة الصحة يعينه وزير الصحة أو من ينيبه.

ب - تشكل بقرار من   وزير الداخلية  وبقدر الحاجة لجان فرعية في المناطق، وتتكون كل لجنة من:

1 - مستشار'),
('boe26-39776b3fe51d18209d5b0fb6','cmpz5yccq027jcwg2f3dmype7','تقوم اللجان المحلية بتطبيق الاختصاص المحدد لها في المادتين (20 ،26) من هذا النظام، وتختص اللجان الفرعية بالفصل في الموضوعات التالية:

أ - طلبات تصحيح أو تعديل قيود الأحوال المدنية، وتظلمات رفض القيد. على أنه فيما يتعلق بتعديل تاريخ الميلاد فيستمر العمل بالقرارات والتعليمات المطبقة حاليا حتى يتم وضع القواعد الخاصة بذلك بقرار من   مجلس الوزراء.
ب - التحقيق مع مخالفي أحكام هذا النظام ولوائحه وتوقيع العقوبات والجزاءات المقررة عليهم.
جـ - الموضوعات الأخرى التي تحال إليها من   إدارة الأحوال المدنية .','2001-08-20','مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 / 1422 هـ ، لتكون بالنص التالى:

تقوم اللجان المحلية بتطبيق الاختصاص المحدد لها في المادتين (20 ،26) من هذا النظام، وتختص اللجان الفرعية بالفصل في الموضوعات التالية:

أ - طلبات تصحيح أو تعديل قيود الأحوال المدنية، وتظلمات رفض القيد. على أنه فيما يتعلق بتعديل تاريخ الميلاد فيستمر العمل بالقرارات والتعليمات المطبقة حاليا حتى يتم وضع القواعد الخاصة بذلك بقرار من   مجلس الوزراء.
ب - التحقيق مع مخالفي أحكام هذا النظام ولوائحه وتوقيع العقوبا'),
('boe26-1581f58675039175a368e61e','cmpz5ycnv027ncwg2k9jljyv3','استثناء مما نصت عليه المادة (84) يجوز للمحكوم عليهم التظلم من قرارات اللجان الفرعية الصادرة ضدهم بالغرامة أو السجن أو بهما معا، أمام ديوان المظالم خلال ستين يوما من تاريخ إبلاغهم بالقرار.','2001-08-20','مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بالمرسوم الملكي رقم (م/25) وتاريخ 1 / 6 / 1422 هـ ، لتكون بالنص الآتى:

استثناء مما نصت عليه المادة (84) يجوز للمحكوم عليهم التظلم من قرارات اللجان الفرعية الصادرة ضدهم بالغرامة أو السجن أو بهما معا، أمام ديوان المظالم خلال ستين يوما من تاريخ إبلاغهم بالقرار.'),
('boe26-ebb797c8cc85cc1534969fc4','cmpz5ycz0027rcwg2cs2e8c2j','تختص   هيئة الأحوال المدنية المركزية    بالنظر والفصل في الموضوعات التالية:

أ - الفصل في الطعون الموجهة ضد قرارات اللجان الفرعية والمحلية.
ب - التصديق على محاضر فحص السجلات.
جـ - إبداء الرأي في كل ما يحيله إليها   وزير الداخلية    من مسائل تتعلق بالأحوال المدنية.','2001-08-20','مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بالمرسوم الملكي رقم (م/25) وتاريخ 1 / 6 / 1422 هـ ، لتكون بالنص الآتى:

تختص   هيئة الأحوال المدنية المركزية    بالنظر والفصل في الموضوعات التالية:

أ - الفصل في الطعون الموجهة ضد قرارات اللجان الفرعية والمحلية.
ب - التصديق على محاضر فحص السجلات.
جـ - إبداء الرأي في كل ما يحيله إليها   وزير الداخلية    من مسائل تتعلق بالأحوال المدنية.'),
('boe26-7fcf8fb9283cf1615a8fe6d6','cmpz5ydl9027zcwg2pweupm89','يعد رب الأسرة في مجال تطبيق هذا النظام هو الأب أو الأم بالنسبة إلى  الأولاد القصّر','2019-07-30','مرسوم ملكي رقم م/134 وتاريخ 27/11/1440هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عُدلت هذه المادة بموجب المرسوم الملكي رقم (م / 134) وتاريخ 27 / 11 /1440هـ، لتكون بالنص الآتي: "يعد رب الأسرة في مجال تطبيق هذا النظام هو الأب أو الأم بالنسبة إلى  الأولاد القصّر".'),
('boe26-b273452f1e67c78ef60eab4a','cmpz6lfl90a2hcwg20yckrpen','يصدر وزير الحج بالاتفاق مع وزير الداخلية ووزير الخارجية - وبالتنسيق مع الهيئة العامة للسياحة والآثار - التعديلات اللازمة على اللائحة التنفيذية لهذا التنظيم بما فيها القواعد المنظمة لتنقل المعتمرين داخل المملكة, وذلك خلال مدة لا تتجاوز ستة أشهر','2014-09-15','قرار مجلس الوزراء رقم 439 وتاريخ 20/11/1435هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/812ac6e0-430d-4c9d-b6cb-a9a700f2080c/1','تم بموجب قرار مجلس الوزراء رقم (439) وتاريخ 20 / 11 /1435هـ 	تعديل المادة (الثالثة عشرة)  لتكون بالنص الآتي:

"يصدر وزير الحج بالاتفاق مع وزير الداخلية ووزير الخارجية - وبالتنسيق مع الهيئة العامة للسياحة والآثار - التعديلات اللازمة على اللائحة التنفيذية لهذا التنظيم بما فيها القواعد المنظمة لتنقل المعتمرين داخل المملكة, وذلك خلال مدة لا تتجاوز ستة أشهر".'),
('boe26-eba85d60de7e78ad52c13747','cmpzcuy3y07wdvtrk7v4tq7c7','يكون للهيئة رئيس يعين بأمر ملكي بمرتبة وزير، ونائب ومساعد يعينان بأمر ملكي بالمرتبة الممتازة','2023-03-28','قرار مجلس الوزراء رقم 620 وتاريخ 1444/9/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/836460dd-2750-40a8-b8b1-a9a700f26ede/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (620) وتاريخ 1444/9/6هـ، لتكون بالنص الآتي:

" يكون للهيئة رئيس يعين بأمر ملكي بمرتبة وزير، ونائب ومساعد يعينان بأمر ملكي بالمرتبة الممتازة".'),
('boe26-e77a52a8ec434893d65d0e34','cmpzcuysb07wkvtrki1nco20d','يتولى نائب رئيس الهيئة ومساعد الرئيس معاونة الرئيس في حضوره، وفقاً لما يحدده الرئيس من صلاحيات لهما، ويتولى نائب الرئيس عمل الرئيس عند غيابه','2023-03-28','قرار مجلس الوزراء رقم 620 وتاريخ 1444/9/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/836460dd-2750-40a8-b8b1-a9a700f26ede/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (620) وتاريخ 1444/9/6هـ، لتكون بالنص الآتي:

" يتولى نائب رئيس الهيئة ومساعد الرئيس معاونة الرئيس في حضوره، وفقاً لما يحدده الرئيس من صلاحيات لهما، ويتولى نائب الرئيس عمل الرئيس عند غيابه".'),
('boe26-52efba84510670fab506db53','cmpzcv8z00awsvtrk4rrz2pdf','1- مع مراعاة الأحكام الواردة في نظام الإجراءات الجزائية، تتابع الوزارة قضايا الإيذاء التي تحيلها إلى جهة الضبط وفقاً لما ورد في المادة (الحادية عشرة) من النظام، وعلى جهة الضبط إحاطة الوزارة بما انتهت إليه من إجراءت حيال كل قضية على حدة. وفي حال كان من تعرض للإيذاء من الأشخاص ذوق الإعاقة، فتستمر في متابعة القضية إلى حين الفصل فيها قضاءً.

2- تتولى الوزارة -عند الحاجة- متابعة حالات الإيذاء بعد الفصل فيها قضاءً لمدة لا تقل عن (6) أشهر','2022-03-09','مرسوم ملكي رقم م/72 وتاريخ 1443/8/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/83f450eb-7985-461f-b053-a9a700f2ba08/1','- صدر تعديل على هذه المادة وذلك بموجب المرسوم الملكي رقم (م/72) وتاريخ 1443/8/6هـ، لتكون بالنص الآتي:

"1- مع مراعاة الأحكام الواردة في نظام الإجراءات الجزائية، تتابع الوزارة قضايا الإيذاء التي تحيلها إلى جهة الضبط وفقاً لما ورد في المادة (الحادية عشرة) من النظام، وعلى جهة الضبط إحاطة الوزارة بما انتهت إليه من إجراءت حيال كل قضية على حدة. وفي حال كان من تعرض للإيذاء من الأشخاص ذوق الإعاقة، فتستمر في متابعة القضية إلى حين الفصل فيها قضاءً.

2- تتولى الوزارة -عند الحاجة- متابعة حالات الإيذاء بعد ا'),
('boe26-73d3de50633e41e23833295d','cmpz5x82z01tfcwg2nh2a4fky','أ- يجب أن تحمل كل دراجة آلية لوحة واحدة، واضحة، ومقروءة، تثبت على مؤخرتها، ولا يجوز السير دونها.

ب- يجب أن تحمل كل مقطورة أو نصف مقطورة رقم لوحة المركبة القاطرة إذا كان حجمها يحجب رؤية تلك اللوحة، وأن تحمل كل مقطورة أو نصف مقطورة لوحة خاصة بها بحسب ما تحدده اللائحة.

ج- دون إخلال بالأحكام ذات الصلة بالمقطورة ونصف المقطورة الواردة في النظام، تحدد اللائحة الأحكام التي تخضع لها المقطورة ونصف المقطورة من بين أحكام النظام ذات الصلة بالمركبة، وذلك بما يتفق مع طبيعة المقطورة ونصف المقطورة','2024-04-07','مرسوم ملكي رقم م/207 وتاريخ 1445/9/28هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/85364e57-c01e-41ba-8def-a9a700f183e9/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/207) وتاريخ 1445/9/28هـ ، لتكون بالنص الآتي:

"أ- يجب أن تحمل كل دراجة آلية لوحة واحدة، واضحة، ومقروءة، تثبت على مؤخرتها، ولا يجوز السير دونها.

ب- يجب أن تحمل كل مقطورة أو نصف مقطورة رقم لوحة المركبة القاطرة إذا كان حجمها يحجب رؤية تلك اللوحة، وأن تحمل كل مقطورة أو نصف مقطورة لوحة خاصة بها بحسب ما تحدده اللائحة.

ج- دون إخلال بالأحكام ذات الصلة بالمقطورة ونصف المقطورة الواردة في النظام، تحدد اللائحة الأحكام التي تخضع لها المقطورة ونصف المقطورة'),
('boe26-3b202eb133974662d48f6e0b','cmpz805dr0cbp7b6w8t5wsxaz','مع مراعاة أحكام الحالات المختلفة المنصوص عليها في هذا النظام، يسوى المعاش عن مدة الخدمة بواقع جزء من أربعين جزءًا من المرتب الشهري الأخير وذلك عن كل سنة من سنوات الخدمة المحسوبة في التقاعد، على ألا تتجاوز أربعين سنة .','1976-10-14','مرسوم ملكي رقم م/75 وتاريخ 21/10/1396هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/859d4e56-627b-4766-a7aa-a9a700f23975/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/75) وتاريخ 21 /10 /1396 هـ ، لتكون كما يلى :

مع مراعاة أحكام الحالات المختلفة المنصوص عليها في هذا النظام، يسوى المعاش عن مدة الخدمة بواقع جزء من أربعين جزءًا من المرتب الشهري الأخير وذلك عن كل سنة من سنوات الخدمة المحسوبة في التقاعد، على ألا تتجاوز أربعين سنة .'),
('boe26-fbec9df37f59ab11f6d0b34e','cmpz806p20cc57b6wknehqxv3','المستحقون عن صاحب المعاش هم: الزوج أو الزوجة، والأم والأب، والابن والبنت، وابن وبنت الابن الذي توفي في حياة صاحب المعاش، والأخ والأخت، والجد والجدة. وفيما عدا الزوجة والابن والبنت، فيشترط لاستحقاق الشخص أن يكون معتمداً في إعالته على صاحب المعاش عند وفاته. ويحدد مجلس إدارة المؤسسة العامة للتقاعد بقرار منه متى يعتبر الشخص معتمداً في إعالته على صاحب المعاش، وتاريخ بدء صرف الاستحقاق، وإجراءات إثبات ذلك','2021-06-03','مرسوم ملكي رقم م/93 وتاريخ 1442/10/22هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/859d4e56-627b-4766-a7aa-a9a700f23975/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/93) وتاريخ 1442/10/22هـ ، لتكون بالنص الآتي: "المستحقون عن صاحب المعاش هم: الزوج أو الزوجة، والأم والأب، والابن والبنت، وابن وبنت الابن الذي توفي في حياة صاحب المعاش، والأخ والأخت، والجد والجدة. وفيما عدا الزوجة والابن والبنت، فيشترط لاستحقاق الشخص أن يكون معتمداً في إعالته على صاحب المعاش عند وفاته. ويحدد مجلس إدارة المؤسسة العامة للتقاعد بقرار منه متى يعتبر الشخص معتمداً في إعالته على صاحب المعاش، وتاريخ بدء صرف الاستحقاق، وإجراءات إثبات ذلك"'),
('boe26-055e7d1e7072cf0d7100c41b','cmpz808lg0ccv7b6wkxdup063','إذا لم يعد الموظف متمتعاً بالجنسية العربية السعودية، يُمنح مكافأة تحسب وفق أحكام المادة (الثالثة والعشرين) من هذا النظام','2022-03-23','مرسوم ملكي رقم م/80 وتاريخ 1443/8/20هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/859d4e56-627b-4766-a7aa-a9a700f23975/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/80) وتاريخ 1443/8/20هـ، لتكون بالنص الآتي: "إذا لم يعد الموظف متمتعاً بالجنسية العربية السعودية، يُمنح مكافأة تحسب وفق أحكام المادة (الثالثة والعشرين) من هذا النظام".'),
('boe26-19ec982a8b5d174b37c0e758','cmpz6fuy0081pcwg2m1hnhqbb','تتولى المحكمة المختصة الفصل في جميع المخالفات والمنازعات ودعاوى المطالبة بالتعويض الناشئة من تطبيق أحكام هذا النظام','2018-09-19','مرسوم ملكي رقم م/10 وتاريخ 1440/1/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/85eb2897-bec6-4c0c-b1d7-ac7c008ec09c/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/10) وتاريخ 1440/1/9هـ، لتصبح بالنص الآتي:

" المادة (الثالثة عشرة): تتولى المحكمة المختصة الفصل في جميع المخالفات والمنازعات ودعاوى المطالبة بالتعويض الناشئة من تطبيق أحكام هذا النظام".'),
('boe26-85971e25961633737ec13f5f','cmpz6fwfy0829cwg29ocd9bbg','1- للنيابة العامة أن تطلب منع سفر من يثبت التحقيق ارتكابه مخالفة لأحكام النظام إلى أن يصدر الحكم النهائي في القضية.

2- لوزارة الداخلية، إذا صدر حكم نهائي بإدانة غير السعودي بارتكابه أياً من المخالفات المنصوص عليها في المادة (الثانية) من النظام، إبعاده من المملكة ومنعه من دخولها، وذلك وفقاً لضوابط تضعها وزارة الداخلية والوزارة ووزارة الاستثمار','2021-08-05','مرسوم ملكي رقم م/109 وتاريخ 1442/12/26هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/85eb2897-bec6-4c0c-b1d7-ac7c008ec09c/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/109) وتاريخ 1442/12/26هـ، لتكون بالنص الآتي:

" 1- للنيابة العامة أن تطلب منع سفر من يثبت التحقيق ارتكابه مخالفة لأحكام النظام إلى أن يصدر الحكم النهائي في القضية.

2- لوزارة الداخلية، إذا صدر حكم نهائي بإدانة غير السعودي بارتكابه أياً من المخالفات المنصوص عليها في المادة (الثانية) من النظام، إبعاده من المملكة ومنعه من دخولها، وذلك وفقاً لضوابط تضعها وزارة الداخلية والوزارة ووزارة الاستثمار".'),
('boe26-7375fd977fc609dffdadd0be','cmpz6fwqr082dcwg2rauql2x0','تضمَّن المحكمة المختصة حكمها - الصادر بعقوبة السجن في إحدى المخالفات المنصوص عليها في المواد السابقة - النص على نشر ملخصه على نفقة المخالف، وللمحكمة المختصة النشر فيما عدا عقوبة السجن، وتحدد المحكمة طريقة النشر إما في إحدى الصحف المحلية أو في أي وسيلة أخرى مناسبة، وذلك بحسب نوع المخالفة المرتكبة وجسامتها وتأثيرها، على أن يكون النش بعد اكتساب الحكم الصفة النهائية','2018-07-11','مرسوم ملكي رقم م/108 وتاريخ 1439/10/27هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/85eb2897-bec6-4c0c-b1d7-ac7c008ec09c/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/108) وتاريخ 1439/10/27هـ، لتكون بالنص الآتي: 

"تضمَّن المحكمة المختصة حكمها - الصادر بعقوبة السجن في إحدى المخالفات المنصوص عليها في المواد السابقة - النص على نشر ملخصه على نفقة المخالف، وللمحكمة المختصة النشر فيما عدا عقوبة السجن، وتحدد المحكمة طريقة النشر إما في إحدى الصحف المحلية أو في أي وسيلة أخرى مناسبة، وذلك بحسب نوع المخالفة المرتكبة وجسامتها وتأثيرها، على أن يكون النش بعد اكتساب الحكم الصفة النهائية".'),
('boe26-6ec18d2212cec24cbeccd828','cmpz6fx1k082hcwg2lc40bdht','يجوز للوزير - في حالة الضرورة أو الاستعجال - إصدار أمر بالحجز التحفظي على منتجٍ وسحبه من الأسواق عند الاشتباه في غشه على أن يعرض أمر الحجز خلال مدة لا تزيد على (اثنتين وسبعين) ساعة على المحكمة المختصة على النحو المبين في اللائحة، لتأكيد الحجز أو إلغائه','2018-09-19','مرسوم ملكي رقم م/10 وتاريخ 1440/1/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/85eb2897-bec6-4c0c-b1d7-ac7c008ec09c/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/10) وتاريخ 1440/1/9هـ، لتصبح بالنص الآتي:

"المادة (السابعة والعشرون): يجوز للوزير - في حالة الضرورة أو الاستعجال - إصدار أمر بالحجز التحفظي على منتجٍ وسحبه من الأسواق عند الاشتباه في غشه على أن يعرض أمر الحجز خلال مدة لا تزيد على (اثنتين وسبعين) ساعة على المحكمة المختصة على النحو المبين في اللائحة، لتأكيد الحجز أو إلغائه".'),
('boe26-c24b822afacbc3cb52f1b4c3','cmpz5ur8r00zpcwg28hi7tdxh','يكون للمكتبة   مجلس أمناء    يتكون من :
- رئيس للمجلس وخمسة أعضاء ممن لهم اهتمام بشئون المكتبات، يتم اختيارهم بأمر ملكي وتكون مدة عضويتهم ثلاث سنوات قابلة للتجديد مرتين.
- أمين للمكتبة عضواً','1996-08-08','مرسوم ملكي رقم م/2 وتاريخ 24/3/1417هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/891a3908-3c1b-4b06-85ac-a9a700f17132/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/2) وتاريخ 24/ 3/ 1417هـ ، لتصبح بالنص الآتي :

" يكون للمكتبة   مجلس أمناء    يتكون من :
- رئيس للمجلس وخمسة أعضاء ممن لهم اهتمام بشئون المكتبات، يتم اختيارهم بأمر ملكي وتكون مدة عضويتهم ثلاث سنوات قابلة للتجديد مرتين.
- أمين للمكتبة عضواً  ".'),
('boe26-2e878f5282bede3f3c263a6e','cmpz6r6ej0c25cwg2jeogd9ol','تصرف شهريا علاوة تدريس تعادل (25% من أول مربوط الرتبة للضباط القائمين فعلا بالتدريس في الكليات والمعاهد والمدارس والمراكز التعليمية العسكرية، وكذلك مدرسي الطيران الجوي المتفرغين للتدريس، كما يصرف ذلك للضباط الذين تتطلب طبيعة عملهم القيام بالتدريس لمواجهة حالات تدريب مؤقتة حسبما يقرره الوزير.','1977-09-03','مرسوم ملكي رقم م/56 وتاريخ 1397/9/20هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/56) وتاريخ 1397/9/20هـ، ليصبح نصها كالآتي: 

تصرف شهريا علاوة تدريس تعادل (25% من أول مربوط الرتبة للضباط القائمين فعلا بالتدريس في الكليات والمعاهد والمدارس والمراكز التعليمية العسكرية، وكذلك مدرسي الطيران الجوي المتفرغين للتدريس، كما يصرف ذلك للضباط الذين تتطلب طبيعة عملهم القيام بالتدريس لمواجهة حالات تدريب مؤقتة حسبما يقرره الوزير.

 '),
('boe26-5b6ceb11eaa52d7e59614d2a','cmpz6r7o90c2jcwg2tr7xbh2v','إذا أمضى الضابط من رتبة رائد فما دون أرب سنوات في رتبته بالإضافة إلى المدة المقررة في المادة (18) من هذه النظام ولم تتوافر شروط الترقية المنصوص عليها في المادة (21) – تنهى خدماته ويعامل بموجب النظام','2002-12-01','مرسوم ملكي رقم م/37 وتاريخ 1423/9/26هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','-  عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/37) وتاريخ 1423/9/26هـ، ليكون نصها كالآتي: "إذا أمضى الضابط من رتبة رائد فما دون أرب سنوات في رتبته بالإضافة إلى المدة المقررة في المادة (18) من هذه النظام ولم تتوافر شروط الترقية المنصوص عليها في المادة (21) – تنهى خدماته ويعامل بموجب النظام".'),
('boe26-49c560dd26186c72e8fe8fb2','cmpz6r8az0c2rcwg2wbjdo8u9','إذا أمضى اللواء ثلاث سنوات في الخدمة ولم يصدر امر بتمديد خدمته فيحال للتقاعد ويجوز مد خدمته ستين قابلة للتجديد عدة مرات وذلك بقرار من القائد الأعلى للقوات المسلحة بناء على اقتراح رئيس مجلس الوزراء وبعد توصية الوزير مالم يبلغ سن التقاعد في رتبته قبل ذلك.','1983-09-07','مرسوم ملكي رقم م/58 وتاريخ 1403/11/30هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/58) وتاريخ 1403/11/30هـ، ليصبح نصها كما يلي: إذا أمضى اللواء ثلاث سنوات في الخدمة ولم يصدر امر بتمديد خدمته فيحال للتقاعد ويجوز مد خدمته ستين قابلة للتجديد عدة مرات وذلك بقرار من القائد الأعلى للقوات المسلحة بناء على اقتراح رئيس مجلس الوزراء وبعد توصية الوزير مالم يبلغ سن التقاعد في رتبته قبل ذلك.'),
('boe26-1445fa34116d02145abe0e52','cmpz6r8gn0c2tcwg2tjosmt81','تكون الترقية إلى رتبة فريق بالاختيار المطلق بأمر من القائد الأعلى لكافة القوات العسكرية بناءً على اقتراح رئيس مجلس الوزراء وتوصية الوزير وذلك من بين الضباط الحاصلين على رتبة لواء الذين أمضوا أربع سنوات على الأقل في هذه الرتبة وتكون مدة شغل الضابط لرتبة فريق أربع سنوات، قابلة للتجديد لمدة لا تزيد على أربع سنوات أخرى وذلك أمر من القائد الأعلى لكافة القوات العسكرية بناءً على اقتراح رئيس مجلس الوزراء وتوصية الوزير','2008-08-27','مرسوم ملكي رقم م/54 وتاريخ 1429/8/26هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','-  عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/54) وتاريخ 1429/8/26هـ، لتصبح بالنص الآتي: "تكون الترقية إلى رتبة فريق بالاختيار المطلق بأمر من القائد الأعلى لكافة القوات العسكرية بناءً على اقتراح رئيس مجلس الوزراء وتوصية الوزير وذلك من بين الضباط الحاصلين على رتبة لواء الذين أمضوا أربع سنوات على الأقل في هذه الرتبة وتكون مدة شغل الضابط لرتبة فريق أربع سنوات، قابلة للتجديد لمدة لا تزيد على أربع سنوات أخرى وذلك أمر من القائد الأعلى لكافة القوات العسكرية بناءً على اقتراح رئيس مجلس الوزراء وت'),
('boe26-bc9728b214159dd59d4a1fcd','cmpz6r9w20c3bcwg2b54t1kp7','( أ – يتم اختيار نائب رئيس هيئة الأركان العامة وقائد القوات البرية وقائد القوات الجوية وقائد القوات البحرية وقائد قوات الدفاع الجوي بأمر من القائد الأعلى للقوات المسلحة بناء على توصية وزير الدفاع والطيران والمفتش العام).

ب – يتم اختيار رؤساء هيئات القوات المسلحة بقرار من الوزير بناء على توصية من رئيس هيئة الأركان العامة)','1986-07-16','مرسوم ملكي رقم م/25 وتاريخ 1406/11/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/25) وتاريخ 1406/11/9هـ، لتكون بالنص الآتي:

( أ – يتم اختيار نائب رئيس هيئة الأركان العامة وقائد القوات البرية وقائد القوات الجوية وقائد القوات البحرية وقائد قوات الدفاع الجوي بأمر من القائد الأعلى للقوات المسلحة بناء على توصية وزير الدفاع والطيران والمفتش العام).

ب – يتم اختيار رؤساء هيئات القوات المسلحة بقرار من الوزير بناء على توصية من رئيس هيئة الأركان العامة)

 '),
('boe26-5eda2266f0ecb32409060476','cmpz6r9w20c3bcwg2b54t1kp7','يتم اختيار نائب رئيس هيئة الأركان العامة وقائد القوات البرية وقائد القوات الجوية وقائد القوات البحرية وقائد قوات الدفاع الجوي وقائد قوة الصواريخ الاستراتيجية بأمر من القائد الأعلى لكافة القوات العسكرية بناءً على توصية وزير الدفاع','2017-04-25','مرسوم ملكي رقم م/81 وتاريخ 1438/7/28هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/81) وتاريخ 1438/7/28هـ، لتصبح على النحو الآتي: "يتم اختيار نائب رئيس هيئة الأركان العامة وقائد القوات البرية وقائد القوات الجوية وقائد القوات البحرية وقائد قوات الدفاع الجوي وقائد قوة الصواريخ الاستراتيجية بأمر من القائد الأعلى لكافة القوات العسكرية بناءً على توصية وزير الدفاع".'),
('boe26-c2c1acbfb5a9d9746edc5ea7','cmpz6ra1q0c3dcwg24ceu2jm7','(يتم بتوصية من لجنة الضباط العليا نقل واثبات الضباط في قيادة القوات البرية الذين يشغلون مناصب قيادية من مستوى كتيبة وما يعاد لها فأعلى ومساعديهم وأركان الألوية وما يعاد لهم فأعلى والملحقين العسكريين ومساعديهم وضباط الاتصال ومساعديهم وكذلك ما يقابلهم في قيادات القوات الجوية والبحرية والدفاع الجوي).','1986-07-16','مرسوم ملكي رقم م/25 وتاريخ 1406/11/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة، وذلك بموجب المرسوم الملكي رقم (م/25) وتاريخ 1406/11/9هـ، لتكون بالنص الآتي: (يتم بتوصية من لجنة الضباط العليا نقل واثبات الضباط في قيادة القوات البرية الذين يشغلون مناصب قيادية من مستوى كتيبة وما يعاد لها فأعلى ومساعديهم وأركان الألوية وما يعاد لهم فأعلى والملحقين العسكريين ومساعديهم وضباط الاتصال ومساعديهم وكذلك ما يقابلهم في قيادات القوات الجوية والبحرية والدفاع الجوي).'),
('boe26-59b2321e0e28a79c9f1912f4','cmpz6ra1q0c3dcwg24ceu2jm7','يتم اختيار نائب رئيس هيئة الأركان العامة وقائد القوات البرية وقائد القوات الجوية وقائد القوات البحرية وقائد قوات الدفاع الجوي وقائد قوة الصواريخ الاستراتيجية بأمر من القائد الأعلى لكافة القوات العسكرية بناءً على توصية وزير الدفاع','2017-04-25','مرسوم ملكي رقم م/81 وتاريخ 1438/7/28هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/81) وتاريخ 1438/7/28هـ، لتصبح على النحو الآتي: "يتم اختيار نائب رئيس هيئة الأركان العامة وقائد القوات البرية وقائد القوات الجوية وقائد القوات البحرية وقائد قوات الدفاع الجوي وقائد قوة الصواريخ الاستراتيجية بأمر من القائد الأعلى لكافة القوات العسكرية بناءً على توصية وزير الدفاع".'),
('boe26-5b3af24a06d654daae9f8807','cmpz6rais0c3jcwg2l1a3tqx5','يجري نقل واثبات الضباط داخل كل قوة بالقوات المسلحة على الوجه الآتي: 

من رتبة مقدم فما فوق بتوصية من لجنة الضباط العليا.

من رتبة رائد فما دون بقرار من قائد القوة.','1989-01-17','مرسوم ملكي رقم م/40 وتاريخ 1409/6/10هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','-    عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/40) وتاريخ 1409/6/10هـ، لتكون كما يلي: " يجري نقل واثبات الضباط داخل كل قوة بالقوات المسلحة على الوجه الآتي: 

من رتبة مقدم فما فوق بتوصية من لجنة الضباط العليا.

من رتبة رائد فما دون بقرار من قائد القوة.'),
('boe26-6e057222e4e26129f3354b2b','cmpz7zrxq0c6n7b6wefiwv269','يستحق الضابط الذي يصاب بجرح أو مرض – يمنعه من أداء عمله بصفة مؤقتة، ويكون ذلك أثناء عمله وبسببه – إجازة مرضية بدلاً من الإجازة المنصوص عليها في المادة (95) مدتها سنة ونصف السنة براتب كامل، فإن لم يعد إلى عمله بعد انتهاء هذه المدة يعرض أمره على اللجنة الطبية لتقرر إما التوصية بإحالته إلى التقاعد أو تمديد إجازته مع تحديد المدة الإضافية، ويصرف له في هذه الحالة نصف الراتب','2002-12-01','مرسوم ملكي رقم م/37 وتاريخ 1423/9/26هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/37) وتاريخ 1423/9/26هـ، ليكون نصها كالآتي: "يستحق الضابط الذي يصاب بجرح أو مرض – يمنعه من أداء عمله بصفة مؤقتة، ويكون ذلك أثناء عمله وبسببه – إجازة مرضية بدلاً من الإجازة المنصوص عليها في المادة (95) مدتها سنة ونصف السنة براتب كامل، فإن لم يعد إلى عمله بعد انتهاء هذه المدة يعرض أمره على اللجنة الطبية لتقرر إما التوصية بإحالته إلى التقاعد أو تمديد إجازته مع تحديد المدة الإضافية، ويصرف له في هذه الحالة نصف الراتب".'),
('boe26-5d3e92402c241796b36c2ffa','cmpz6re5s0c4tcwg202r5d3zf','يحرم الضابط الطيار، والضابط مشغل أنظمة التسليح على الطائرات المقاتلة، من علاوة الطيران، متى ثبت تقصيره في أداء واجباته المتعلقة بأعمال الطيران، أو ثبت ضعف مستوى طيرانه، أو لم يُتم الحد الأدنى لعدد ساعات الطيران المقررة لكل رتبة. وتحدد لجنة الضباط العليا مدى هذه الواجبات وكيفية أدائها بناء على اقتراح قائد القوات الجوية. ويكون الحرمان – كلياً أو جزئياً – بنسبة تقصير الضابط في أداء واجباته المتعلقة بأعمال الطيران','2003-06-11','مرسوم ملكي رقم م/19 وتاريخ 1424/4/11هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','-  عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/19) وتاريخ 1424/4/11هـ، لتصبح بالنص التالي: "يحرم الضابط الطيار، والضابط مشغل أنظمة التسليح على الطائرات المقاتلة، من علاوة الطيران، متى ثبت تقصيره في أداء واجباته المتعلقة بأعمال الطيران، أو ثبت ضعف مستوى طيرانه، أو لم يُتم الحد الأدنى لعدد ساعات الطيران المقررة لكل رتبة. وتحدد لجنة الضباط العليا مدى هذه الواجبات وكيفية أدائها بناء على اقتراح قائد القوات الجوية. ويكون الحرمان – كلياً أو جزئياً – بنسبة تقصير الضابط في أداء واجباته المتعلقة بأ'),
('boe26-949dc95960a82c5a5399bb21','cmpz7zqmb0c657b6wqnnv7i9n','الإجازات هي: اعتيادية، عرضية، ميدانية، استثنائية، مرضية، مرافقة دراسية','2020-11-12','مرسوم ملكي رقم م/28 وتاريخ 1442/3/26هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/28) وتاريخ 1442/3/26هـ، لتكون بالنص الآتي: "الإجازات هي: اعتيادية، عرضية، ميدانية، استثنائية، مرضية، مرافقة دراسية".'),
('boe26-546ef071078c9343c5e89ddd','cmpz7zrsg0c6l7b6w1xsbhbg2','يستحق الضابط إجازة مرضية، في مدة ثلاث سنوات، مدتها اثنا عشر شهراً بالراتب الفعلي، وستة أشهر بنصف الراتب الفعلي','2005-08-13','مرسوم ملكي رقم م/34 وتاريخ 1426/7/8هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/34) وتاريخ 1426/7/8هـ، لتصبح بالنص الآتي: "يستحق الضابط إجازة مرضية، في مدة ثلاث سنوات، مدتها اثنا عشر شهراً بالراتب الفعلي، وستة أشهر بنصف الراتب الفعلي".'),
('boe26-09534ee7e32a10e2ebfa0de3','cmpz7zvg10c7x7b6wpvzi0aws','إذا قدم الضابط طلباً للإحالة إلى التقاعد أو الاستقالة فللمراجع المختصة حق رفضه أو قبوله، ويخطر الضابط بالقبول أو الرفض في مدة أقصاها ثلاثة أشهر، أما إذا كان الضابط رهن التحقيق أو المحاكمة فيجب إرجاء البتّ في الطلب إلى أن ينتهي التحقيق بالحفظ أو المحاكمة، وفي الحالة الأخيرة يُنتظر أن يصدّق على الحكم ثم يُنظر في طلبه على ضوء النتيجة','2020-11-12','مرسوم ملكي رقم م/28 وتاريخ 1442/3/26هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/28) وتاريخ 1442/3/26هـ، لتكون بالنص الآتي: "إذا قدم الضابط طلباً للإحالة إلى التقاعد أو الاستقالة فللمراجع المختصة حق رفضه أو قبوله، ويخطر الضابط بالقبول أو الرفض في مدة أقصاها ثلاثة أشهر، أما إذا كان الضابط رهن التحقيق أو المحاكمة فيجب إرجاء البتّ في الطلب إلى أن ينتهي التحقيق بالحفظ أو المحاكمة، وفي الحالة الأخيرة يُنتظر أن يصدّق على الحكم ثم يُنظر في طلبه على ضوء النتيجة".'),
('boe26-283d599a8b020bc2ea43f9c8','cmpz7zwm30c8d7b6wsjmpm25u','(عند غياب رئيس اللجنة العليا يحل محله من يكلف بالقيام بعمله وإذا غاب أحد قادة القوات فيحل محله نائبه)','1986-07-16','مرسوم ملكي رقم م/25 وتاريخ 1406/11/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/25) وتاريخ 1406/11/9هـ، لتكون بالنص الآتي 

(عند غياب رئيس اللجنة العليا يحل محله من يكلف بالقيام بعمله وإذا غاب أحد قادة القوات فيحل محله نائبه)'),
('boe26-fa774572b2f21992e24ec5de','cmpz7zyd40c917b6wzdhwt513','(تشكل لجان ضباط فرعية في فروع القوات المسلحة –القوات البرية- القوات الجوية- القوات البحرية- قوات الدفاع الجوي- وتتكون كل منها من خمسة ضباط على مستوى جيد من الثقافة والتخطيط وحسن الادراك ويرأسها أقدم ضابط منهم على أن يكون أحدهم مدير إدارة شئون ضباط ذلك الفرع عضوا وسكرتيرا لها ولا يجوز أن يشترك في هذه اللجان أي من أعضاء لجنة الضباط العليا).','1986-07-16','مرسوم ملكي رقم م/25 وتاريخ 1406/11/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/25) وتاريخ 1406/11/9هـ، لتكون بالنص الآتي: (تشكل لجان ضباط فرعية في فروع القوات المسلحة –القوات البرية- القوات الجوية- القوات البحرية- قوات الدفاع الجوي- وتتكون كل منها من خمسة ضباط على مستوى جيد من الثقافة والتخطيط وحسن الادراك ويرأسها أقدم ضابط منهم على أن يكون أحدهم مدير إدارة شئون ضباط ذلك الفرع عضوا وسكرتيرا لها ولا يجوز أن يشترك في هذه اللجان أي من أعضاء لجنة الضباط العليا).'),
('boe26-9a901a3c5f19c2fe5288faff','cmpz7zyd40c917b6wzdhwt513','تشكل لجان ضباط فرعية في فروع القوات المسلحة – القوات البرية – القوات الجوية – القوات البحرية – قوات الدفاع الجوي – قوة الصواريخ الاستراتيجية – وتتكون كل منها من خمسة ضباط على مستوى جيد من الثقافة والتخطيط وحسن الإدراك ويرأسها أقدم ضابط منهم على أن يكون مدير إدارة شؤون ضباط ذلك الفرع عضواً وسكرتيراً لها ولا يجوز أن يشترك في هذه اللجان أي من أعضاء لجنة الضباط العليا','2017-04-25','مرسوم ملكي رقم م/81 وتاريخ 1438/7/28هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/81) وتاريخ 1438/7/28هـ، لتكون على النحو الآتي: "تشكل لجان ضباط فرعية في فروع القوات المسلحة – القوات البرية – القوات الجوية – القوات البحرية – قوات الدفاع الجوي – قوة الصواريخ الاستراتيجية – وتتكون كل منها من خمسة ضباط على مستوى جيد من الثقافة والتخطيط وحسن الإدراك ويرأسها أقدم ضابط منهم على أن يكون مدير إدارة شؤون ضباط ذلك الفرع عضواً وسكرتيراً لها ولا يجوز أن يشترك في هذه اللجان أي من أعضاء لجنة الضباط العليا".'),
('boe26-9436bdd768c7a90d1eb47ec8','cmpz7zyid0c937b6w5avd017w','(يرشح كل قائد من قادة القوات البرية والجوية والبحرية والدفاع الجوي رئيس وأعضاء لجنة الضباط الفرعية في قواته وذلك وفقاً للمادة (139) من النظام).','1986-07-16','مرسوم ملكي رقم م/25 وتاريخ 1406/11/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/25) وتاريخ 1406/11/9هـ، لتكون بالنص الآتي: (يرشح كل قائد من قادة القوات البرية والجوية والبحرية والدفاع الجوي رئيس وأعضاء لجنة الضباط الفرعية في قواته وذلك وفقاً للمادة (139) من النظام).'),
('boe26-288ed1fe0cbefe2c5c6e9ede','cmpz7zyid0c937b6w5avd017w','يرشح كل قائد من قادة القوات البرية والجوية والبحرية والدفاع الجوي وقوة الصواريخ الاستراتيجية رئيس وأعضاء لجنة الضباط الفرعية في قواته وذلك وفقاً للمادة (139) من النظام','2017-04-25','مرسوم ملكي رقم م/81 وتاريخ 1438/7/28هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/81) وتاريخ 1438/7/28هـ، لتكون بالنص الآتي: "يرشح كل قائد من قادة القوات البرية والجوية والبحرية والدفاع الجوي وقوة الصواريخ الاستراتيجية رئيس وأعضاء لجنة الضباط الفرعية في قواته وذلك وفقاً للمادة (139) من النظام".'),
('boe26-fe4072fb23e9d4bf1fca1a63','cmpz7zz8o0c9d7b6wgrcjgmx2','(ترفع توصيات كل لجنة من لجان الضباط الفرعية بعد أن يتم إقرارها من قائد القوات المختص).','1986-07-16','مرسوم ملكي رقم م/25 وتاريخ 1406/11/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/25) وتاريخ 1406/11/9هـ، لتكون بالنص الآتي: (ترفع توصيات كل لجنة من لجان الضباط الفرعية بعد أن يتم إقرارها من قائد القوات المختص).'),
('boe26-f508cf0e9d47090a1512be2f','cmpz8009g0c9r7b6woras15fr','(تنظم أعمال لجان الضباط الفرعية في القوات المسلحة بقرار يصدر من قائد القوات المختص بناء على توصية مدير إدارة شؤون الضباط في قواته بعد التنسيق مع مدير إدارة شؤون ضباط القوات المسلحة ينظم سير أعمال لجنة الضباط الفرعية في قواته واجتماعاتها والبت في القضايا المنوطة بها وفقا لأحكام هذا النظام).','1986-07-16','مرسوم ملكي رقم م/25 وتاريخ 1406/11/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/25) وتاريخ 1406/11/9هـ، لتكون بالنص الآتي: (تنظم أعمال لجان الضباط الفرعية في القوات المسلحة بقرار يصدر من قائد القوات المختص بناء على توصية مدير إدارة شؤون الضباط في قواته بعد التنسيق مع مدير إدارة شؤون ضباط القوات المسلحة ينظم سير أعمال لجنة الضباط الفرعية في قواته واجتماعاتها والبت في القضايا المنوطة بها وفقا لأحكام هذا النظام).'),
('boe26-c9f2fb928a5979f419b65d7d','cmpz800ep0c9t7b6weh1h2s0g','يُعطى الضابط الذي تلحقه خسارة مادية بسبب عمله، أو قيامه بتأديته، أو قيامه بمهمة رسمية، تعويضاً للخسارة الفعلية، على أن يقدم خلال ثلاثة أشهر من تاريخ وقوع الخسارة طلب التعويض والوثائق المثبتة للخسارة إلى الوزير عن طريق المرجع، وإلا سقط الحق بالمطالبة به، ما لم يكن ثمة عذر شرعي – يقدره الوزير المختص – حال دون تقديم طلب التعويض خلال تلك المدة','2018-07-11','مرسوم ملكي رقم م/107 وتاريخ 1439/10/27هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/107) وتاريخ 1439/10/27هـ، لتكون بالنص الآتي: "يُعطى الضابط الذي تلحقه خسارة مادية بسبب عمله، أو قيامه بتأديته، أو قيامه بمهمة رسمية، تعويضاً للخسارة الفعلية، على أن يقدم خلال ثلاثة أشهر من تاريخ وقوع الخسارة طلب التعويض والوثائق المثبتة للخسارة إلى الوزير عن طريق المرجع، وإلا سقط الحق بالمطالبة به، ما لم يكن ثمة عذر شرعي – يقدره الوزير المختص – حال دون تقديم طلب التعويض خلال تلك المدة".'),
('boe26-6f4bff628cdcfee90032aa38','cmpz6liwt0a3ncwg2zd3x99wb','يكون للمجمع أمين عام يعين ويعفى بقرار من المجلس بناء على اقتراح من رئيسه، ويحدد القرار أجره ومزاياه المالية الأخرى، ويتولى إدارة المجمع في حدود ما يقضي به هذا التنظيم، وما يُقرره المجلس، ويمثله أمام القضاء والهيئات والمؤسسات الأُخرى. وتحدد صلاحياته ومسؤولياته بناءً على لائحة يصدرها المجلس','2022-02-15','قرار مجلس الوزراء رقم 391 وتاريخ 1443/7/14هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8f0b8e8e-a856-4567-9396-a9a700f20b4d/1','-عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (391) وتاريخ 1443/7/14هـ، لتكون بالنص الآتي: "يكون للمجمع أمين عام يعين ويعفى بقرار من المجلس بناء على اقتراح من رئيسه، ويحدد القرار أجره ومزاياه المالية الأخرى، ويتولى إدارة المجمع في حدود ما يقضي به هذا التنظيم، وما يُقرره المجلس، ويمثله أمام القضاء والهيئات والمؤسسات الأُخرى. وتحدد صلاحياته ومسؤولياته بناءً على لائحة يصدرها المجلس".'),
('boe26-bd48b58c6599c0bf51e9310c','cmpwi2xtg00hjnxfftdpf43p6','يخضع رجال الضبط الجنائي - فيما يتعلق بوظائفهم في الضبط الجنائي المقررة في هذا النظام - لإشراف النيابة العامة. وللنيابة العامة أن تطلب من الجهة المختصة النظر في أمر كل من تقع منه مخالفة لواجباته أو تقصير في عمله، ولها أن تطلب رفع الدعوى التأديبية عليه، وتشعر النيابة العامة بما تم في شأن ذلك الطلب، وذلك دون إخلال بالحق في رفع الدعوى الجزائية','2021-11-04','مرسوم ملكي رقم م/28 وتاريخ 1443/3/29هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8f1b7079-a5f0-425d-b5e0-a9a700f26b2d/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/28) وتاريخ 1443/3/29هـ، لتكون بالنص الآتي: " يخضع رجال الضبط الجنائي - فيما يتعلق بوظائفهم في الضبط الجنائي المقررة في هذا النظام - لإشراف النيابة العامة. وللنيابة العامة أن تطلب من الجهة المختصة النظر في أمر كل من تقع منه مخالفة لواجباته أو تقصير في عمله، ولها أن تطلب رفع الدعوى التأديبية عليه، وتشعر النيابة العامة بما تم في شأن ذلك الطلب، وذلك دون إخلال بالحق في رفع الدعوى الجزائية".'),
('boe26-357a20d67c0e25a5f06bab51','cmpz6lmpk0a4xcwg235y1kgfc','يتولى موظفون من الوزارة أو غيرهم -يصدر بتسميتهم قرار من الوزير- الرقابة على شركات ضيافة الحجاج وشركات تقديم الخدمة والتفتيش عليها وضبط ما يقع منها من مخالفات؛ لتطبيق أحكام النظام والقرارات الصادرة تنفيذًا له.','2025-11-03','مرسوم ملكي رقم م/89 وتاريخ 1447/5/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/962235c2-9fa8-4c1a-b835-aa6400dd851e/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/89) وتاريخ 1447/5/12هـ، لتكون بالنص الآتي:

" يتولى موظفون من الوزارة أو غيرهم -يصدر بتسميتهم قرار من الوزير- الرقابة على شركات ضيافة الحجاج وشركات تقديم الخدمة والتفتيش عليها وضبط ما يقع منها من مخالفات؛ لتطبيق أحكام النظام والقرارات الصادرة تنفيذًا له.'),
('boe26-93414eb670e3f7453f218239','cmpz64x2p04cxcwg2nr3drpg8','يخضع منسوبو الهيئة لأحكام نظام العمل ونظام التأمينات الاجتماعية','2022-04-19','قرار مجلس الوزراء رقم 539 وتاريخ 1443/9/18هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/98642c12-dd48-4148-841d-a9a700f1b3ea/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (539) وتاريخ 1443/9/18هـ. لتكون بالنص الآتي: "يخضع منسوبو الهيئة لأحكام نظام العمل ونظام التأمينات الاجتماعية".')
ON CONFLICT (id) DO NOTHING